      "content": "{\n  \"name\": \"dsh-skill-hub\",\n  \"version\": \"0.3.32\",\n  \"description\": \"dsh web GUI skill hub: browse/search all local skills, per-skill/group toggles, install-time audit (hidden chars, pipe-to-shell), GitHub market with commit pins, local-edit detection, cross-agent import, restorable trash.\",\n  \"type\": \"module\",\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\"\n  },\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./invariant\": {\n      \"types\": \"./lib/types/invariant.d.ts\",\n      \"default\": \"./lib/invariant.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./src/*\": \"./src/*\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-ui-settings\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"dshWorkshop\": {\n    \"schema\": \"omdsh-workshop-package/v1\",\n    \"type\": \"plugin\",\n    \"integration\": {\n      \"protocol\": \"harness-cordis\",\n      \"artifact\": \"cordis.patch.yml\"\n    },\n    \"install\": {\n      \"mode\": \"guided\",\n      \"adapter\": \"third-party\",\n      \"failurePolicy\": \"manual\",\n      \"touchesCurrentBeforeActivation\": false\n    },\n    \"lifecycle\": {\n      \"activation\": \"hot-reload\",\n      \"dispose\": \"supported\"\n    },\n    \"permissions\": [\n      \"fs:read\",\n      \"fs:write\",\n      \"net:https\",\n      \"net:loopback\"\n    ],\n    \"compatibility\": {\n      \"dshVersions\": [\n        \"0.1.7-alpha.1\",\n        \"0.1.7-alpha.2\",\n        \"0.1.7-rc.1\",\n        \"0.1.7-rc.2\",\n        \"0.2.0-rc.1\",\n        \"0.2.0-rc.2\",\n        \"0.2.1-alpha.2\",\n        \"0.2.1-alpha.5\",\n        \"0.2.1-rc.2\",\n        \"0.2.2-alpha.2\",\n        \"0.2.2-alpha.3\",\n        \"0.2.2-rc.1\"\n      ]\n    },\n    \"capability\": {\n      \"id\": \"skill-hub-settings-panel\",\n      \"kind\": \"ui\",\n      \"invocation\": \"Open Settings → Skills panel; GET /api/skill-hub/catalog\",\n      \"expected\": \"The full local skill catalog (all roots) renders as groups and toggles persist an enabled/disabled row without a restart.\"\n    },\n    \"evidence\": {\n      \"install\": null,\n      \"failureIsolation\": null,\n      \"hotReload\": null,\n      \"remove\": null\n    }\n  },\n  \"dependencies\": {\n    \"js-yaml\": \"^4.1.0\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1 || ^4.0.2 || ^4.0.5-alpha.1 || ^4.0.5-alpha.2 || ^4.0.6-alpha.1 || ^4.1.0\",\n    \"@deepseek-ai/dsh-client-connection\": \">=0.1.7-alpha.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-locale\": \">=0.1.7-alpha.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-runtime\": \">=0.1.7-alpha.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-store\": \">=0.1.7-alpha.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-input-trigger\": \">=0.1.7-alpha.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \">=0.1.7-alpha.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \">=0.1.7-alpha.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-host-webserver\": \">=0.1.7-alpha.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-session\": \">=0.1.7-alpha.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-session-query\": \">=0.1.7-alpha.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-settings\": \">=0.1.7-alpha.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-skill\": \">=0.1.7-alpha.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-system-prompt\": \">=0.1.7-alpha.1 <0.3.0-0\",\n    \"@deepseek-ai/schemastery\": \"^3.18.3 || ^3.18.5-alpha.1 || ^3.18.5-alpha.2 || ^3.18.6-alpha.1 || ^3.19.0\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-connection\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-locale\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-runtime\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-store\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-input-trigger\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-settings\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-slots\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-host-webserver\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-session\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-session-query\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-settings\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-skill\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-system-prompt\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/schemastery\": {\n      \"optional\": true\n    },\n    \"react\": {\n      \"optional\": true\n    },\n    \"react-dom\": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.6-alpha.1\",\n    \"@deepseek-ai/dsh-client-connection\": \"^0.2.2-alpha.2\",\n    \"@deepseek-ai/dsh-client-locale\": \"^0.2.2-alpha.2\",\n    \"@deepseek-ai/dsh-client-store\": \"^0.2.2-alpha.2\",\n    \"@deepseek-ai/dsh-client-ui-input-trigger\": \"^0.2.2-alpha.2\",\n    \"@deepseek-ai/dsh-client-ui-plugin-manager\": \"^0.2.2-alpha.2\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"^0.2.2-alpha.2\",\n    \"@deepseek-ai/dsh-client-ui-settings-plugins\": \"^0.2.2-alpha.2\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"^0.2.2-alpha.2\",\n    \"@deepseek-ai/dsh-host-webserver\": \"^0.2.2-alpha.2\",\n    \"@deepseek-ai/dsh-session\": \"^0.2.