      "path": "cordis.patch.yml",
      "content": "# dsh-skill-hub bundle patch: inserts the dual-face plugin row into the web\n# profile roster. Applied as a profile bundle layer (the `dsh.bundle.patch`\n# manifest field) over dsh-base; activate with\n# `dsh plugin --profile <name> add dsh-skill-hub`.\n#\n# The row is a bare plugin by package name: the node half (exports \".\") runs\n# in the host process (skill catalog routes, toggle/create operations), and\n# the `dsh.client` declaration in package.json makes the browser half\n# (exports \"./client\", served at /plugins/<id>/client.js) load in the web GUI.\n- insert:\n    - id: skill-hub\n      name: 'dsh-skill-hub'\n"
    },
    {
      "path": "tsdown.config.ts",
      "content": "/**\n * Standalone build config for dsh-skill-hub (adapted from dsh-web-ui's\n * shared/tsdown.client.ts preset, vendored for a single-package repo).\n *\n * Two artifacts:\n *  - the node half (lib/index.js, lib/invariant.js): plain ESM for the host\n *    process, everything @deepseek-ai external (resolved from the dsh\n *    profile tree at runtime);\n *  - the browser half (lib/client.js): a CJS closure-factory artifact that\n *    calls window.__ModuleLoader__.load({id, factory}) and resolves\n *    externals through the injected require (the loader module table —\n *    cordis DI entities, no globals). CSS Modules are compiled by\n *    lightningcss inside the bundle: importing x.module.css yields the\n *    hashed class map, and the css text auto-injects a\n *    <style data-plugin> tag at factory execution.\n */\nimport { readFile } from 'node:fs/promises'\nimport { basename, dirname, resolve as resolvePath, sep } from 'node:path'\nimport type { UserConfig } from 'tsdown'\nimport { transform } from 'lightningcss'\n\n/** Plugin id stamped into the __ModuleLoader__.load handoff and style tags. */\nconst ID = 'dsh-skill-hub'\n\n/**\n * The shell's shared module table (vendored from dsh-web-ui's\n * shared/web-platform.ts): the only specifiers the browser loader can\n * answer. Everything else must inline.\n *\n * `@deepseek-ai/dsh-client-store` is deliberately NOT in this table: the\n * loader does not answer it, so the client bundle inlines it (see noExternal\n * below) rather than requiring it at runtime.\n */\nconst PLATFORM_MODULES = [\n  'react', 'react/jsx-runtime', 'react-dom', 'react-dom/client', '@deepseek-ai/cordis',\n  '@deepseek-ai/dsh-client-ui-slots',\n  '@deepseek-ai/dsh-client-web-react',\n  '@deepseek-ai/dsh-client-schema-form',\n] as const\n\n/** Externals resolved from the loader module table. */\nconst CLIENT_EXTERNALS: readonly string[] = [...PLATFORM_MODULES]\n\n/**\n * Virtual-id wrapper keeping module CSS away from tsdown's own css pipeline\n * (which requires @tsdown/css). The suffix matters: tsdown's guard matches\n * ids ending in .css, so the virtual id must not.\n */\nconst CSS_VIRTUAL_PREFIX = '\\0dsh-css:'\nconst CSS_VIRTUAL_SUFFIX = '.mjs'\n\n/** Node-half library build. */\nfunction libConfig(): UserConfig {\n  return {\n    name: ID,\n    entry: ['src/index.ts', 'src/invariant.ts'],\n    outDir: 'lib',\n    format: ['esm'],\n    // Emit lib/index.js (not .mjs) to match the package exports map.\n    fixedExtension: false,\n    platform: 'node',\n    target: 'es2024',\n    dts: false,\n    // clean must stay off: a default clean would wipe the lib/types\n    // declarations tsc emitted before tsdown runs (see package.json prebuild).\n    clean: false,\n    // The cordis framework and the host SDK resolve at runtime from the dsh\n    // profile tree, never from this package; their built declarations carry\n    // .ts-suffixed relative imports rolldown cannot follow.\n    external: [\n      '@deepseek-ai/cordis',\n      '@deepseek-ai/dsh-skill',\n      '@deepseek-ai/dsh-host-webserver',\n      '@deepseek-ai/dsh-settings',\n      '@deepseek-ai/dsh-system-prompt',\n    ],\n  }\n}\n\n/** Browser-half bundle. */\nfunction clientConfig(): UserConfig {\n  return {\n    name: ID + '/client',\n    entry: { client: 'src/client/index.tsx' },\n    outDir: 'lib',\n    format: 'cjs',\n    platform: 'browser',\n    dts: false,\n    sourcemap: true,\n    clean: false,\n    external: [...CLIENT_EXTERNALS],\n    // Browser bundles inline node-idiom deps; a require() the module table\n    // cannot answer is a guaranteed runtime throw, so the rule is the table\n    // list itself: no opinion for table entries (external above wins),\n    // bundle everything else.\n    noExternal: (id: string) => (CLIENT_EXTERNALS.includes(id) ? undefined : true),\n    define: {\n      'process.env.NODE_ENV': JSON.stringify(process.env.NODE_ENV ?? 'production'),\n      'import.meta.env.MODE': JSON.stringify(process.env.NODE_ENV ?? 'production'),\n      'import.meta.env': JSON.stringify({ MODE: process.env.NODE_ENV ?? 'production' }),\n    },\n    plugins: [\n      {\n        // CSS Modules: compile with lightningcss, emit a class-map export\n        // plus a self-injecting <style data-plugin> tag.\n        name: 'dsh-css-modules-inline',\n        resolveId(source: string, importer: string | undefined) {\n          if (!source.endsWith('.module.css')) return null\n          const abs = importer !== undefined ? resolvePath(dirname(importer), source) : source\n          return CSS_VIRTUAL_PREFIX + abs + CSS_VIRTUAL_SUFFIX\n        },\n        async load(virtualId: string) {\n          if (!virtualId.startsWith(CSS_VIRTUAL_PREFIX)) return null\n          const fileId = virtualId.slice(CSS_VIRTUAL_PREFIX.length, -CSS_VIRTUAL_SUFFIX.length)\n          // The virtual id otherwise hides the physical stylesheet from Rolldown's watch graph.\n          this.addWatchFile(fileId)\n          const source = await readFile(fileId)\n          const { code, exports: cssExports } = transform({\n            filename: fileId,\n            code: source,\n            cssModules: { pattern: '[hash]_[local]' },\n            minify: true,\n          })\n          const classMap: Record<string, string> = {}\n          // Deterministic sort: lightningcss's export iteration order is\n          // process-dependent, which would churn lib/client.js on rebuild.\n          for (const [local, exp] of Object.entries(cssExports ?? {}).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))) {\n            classMap[local] = exp.name\n          }\n          // One <style data-plugin> per module file; idempotent under re-evaluation.\n          return [\n            'const css = ' + JSON.stringify(code.toString()) + ';',\n            'const tagId = ' + JSON.stringify(ID + '/' + basename(fileId)) + ';',\n            'if (typeof document !== \\'undefined\\' && document.querySelector(\\'style[data-plugin-css=\\' + JSON.stringify(tagId) + \\']\\') === null) {',\n            '  const tag = document.createElement(\\'style\\');',\n            '  tag.dataset.plugin = ' + JSON.stringify(ID) + ';',\n            '  tag.dataset.pluginCss = tagId;',\n            '  tag.textContent = css;',\n            '  document.head.appendChild(tag);',\n            '}',\n            'export default ' + JSON.stringify(classMap) + ';',\n          ].join('\\n')\n        },\n      },\n    ],\n    outputOptions: {\n      entryFileNames: 'client.js',\n      banner: 'window.__ModuleLoader__.load({ id: ' + JSON.stringify(ID) + ', factory: (require) => {',\n      footer: 'return module.exports; } });',\n      intro: 'var module = { exports: {} }; var exports = module.exports;',\n    },\n  }\n}\n\n/** Standalone build: both faces, no workspace phases. */\nexport default (): UserConfig[] => [libConfig(), clientConfig()]\n\n"
    },
    {
      "path": "src/index.ts",
      "content": "/**\n * dsh-skill-hub — host half. Mounts the /api/skill-hub route family (full\n * skill catalog from the official ctx.skills registry, skill detail,\n * enable/disable toggle, new-skill scaffold) plus a system-prompt\n * announcement. The browser half (./client) renders the sidebar entry and\n * the skill hub panel. Everything rides official NPM SDK packages — no dsh\n * source changes.\n */\n\nimport type { Context, Volatile } from '@deepseek-ai/cordis'\nimport type { SkillProviderControl } from '@deepseek-ai/dsh-skill'\nimport type { SettingsForms, SettingsNamespace, SettingsPathOp } from '@deepseek-ai/dsh-settings'\n// dsh's own fork, NOT the plain `schemastery` package: `.volatile()` (and the\n// loader's `fiber.runtime.Config` handling) only exist here. Every official\n// plugin imports it under this name.\nimport z from '@deepseek-ai/schemastery'\n// Type-only, for the `ctx.connection` augmentation (the `/api` trust fence).\nimport type {} from '@deepseek-ai/dsh-client-connection'\nimport type {} from '@deepseek-ai/dsh-host-webserver'\nimport type {} from '@deepseek-ai/dsh-skill'\nimport type {} from '@deepseek-ai/dsh-system-prompt'\nimport type {} from '@deepseek-ai/dsh-session-query'\nimport type {} from '@deepseek-ai/dsh-settings'\nimport { HUB_CONFIG_DEFAULTS, HUB_ENTRY_ID, HEX_COLOR_RE, resolveHubConfig, type HubConfig } from './protocol.ts'\nimport { SkillHubProvider } from './provider.ts'\nimport { hostTrustFence, makeRoutes } from './routes.ts'\nimport { createSkillStatsReader, asPersistenceSeam, type SessionPersistenceLike, type SessionQueryLike, type SkillStatsReader } from './stats.ts'\nimport { SkillHubStore } from './store.ts'\nimport { migrateRenamedDisabledSkills, reconcileDisabledSkills, pruneStaleDisabledSkills } from './reconcile.ts'\nimport { cleanupLeftoverImportDirs, setGithubToken } from './repo.ts'\nimport { dshHome } from './store.ts'\nimport { join } from 'node:path'\nimport { homedir } from 'node:os'\n\n/** Stable cordis plugin name (matches cordis.patch.yml insert id). */\nexport const name = 'skill-hub'\n\n/** Services required before the skill-hub surfaces can mount. `settings` is deliberately NOT here: the plugin reads its own volatile config refs and only reaches for the settings service when it is present (issue #11). */\nexport const inject = ['webServer', 'skills', 'systemPrompt']\n\n/**\n * Plugin config, validated by the same-named schemastery schema.\n *\n * dsh 0.1.7 replaced the \"plugin registers a settings namespace\" model with\n * \"the Loader entry's Config IS the settings namespace\", so this one schema is\n * both the composition config and the settings page. Every field is volatile:\n * the Loader re-resolves volatile values in place and re-enters apply()\n * instead of rebuilding the fiber, and only volatile fields are writable\n * through the settings transport.\n */\nexport interface Config {\n  /** When true (default), a system-prompt section announces the hub to every agent. */\n  announceToAgent: Volatile<boolean>\n  /** Master switch for the plugin (routes, prompt section). */\n  enabled: Volatile<boolean>\n  /** Show per-skill invocation count chip. Default true. */\n  showUseCount: Volatile<boolean>\n  /** Show per-skill last-used relative time. Default true. */\n  showUseTime: Volatile<boolean>\n  /** Show group-header usage summaries (count + last used). Default true. */\n  showGroupSummary: Volatile<boolean>\n  /** 模型可调圆点颜色（#rrggbb）；缺省用面板默认色。 */\n  dotModelColor: Volatile<string | undefined>\n  /** 用户可调圆点颜色（#rrggbb）；缺省用面板默认色。 */\n  dotUserColor: Volatile<string | undefined>\n  /** GitHub token；`role('secret')` 让 settings 层统一脱敏，缺省为匿名。 */\n  githubToken: Volatile<string | undefined>\n  /** 统计滚动窗口天数：只统计最近 N 天的使用；0 = 全部历史。 */\n  statsWindowDays: Volatile<number>\n  /** 自动统计扫描间隔（分钟，最小 1）。 */\n  statsScanMinutes: Volatile<number>\n}\n\n/**\n * The durable field schemas, plain (non-volatile) so the same definitions can\n * back both the live view below and the wire form the settings page renders\n * from `.toJSON()`. `description` is what the auto-generated page shows with\n * each row; `role('secret')` makes the settings layer redact the value on\n * every wire read.\n */\nconst ConfigFields = {\n  enabled: z.boolean().default(HUB_CONFIG_DEFAULTS.enabled).description('关闭后技能中枢的路由、入口与公告全部下线。'),\n  announceToAgent: z.boolean().default(HUB_CONFIG_DEFAULTS.announceToAgent).description('在系统提示中加入本插件说明，用户提到技能管理时 Agent 知道如何协作。'),\n  dotModelColor: z.string().pattern(HEX_COLOR_RE).description('技能行与聊天「/」菜单中「模型可调」圆点的颜色（#rrggbb）。'),\n  dotUserColor: z.string().pattern(HEX_COLOR_RE).description('技能行与聊天「/」菜单中「仅用户可调」圆点的颜色（#rrggbb）。'),\n  showUseCount: z.boolean().default(HUB_CONFIG_DEFAULTS.showUseCount).description('在技能名旁显示调用次数。'),\n  showUseTime: z.boolean().default(HUB_CONFIG_DEFAULTS.showUseTime).description('在技能名行显示最近调用时间。'),\n  showGroupSummary: z.boolean().default(HUB_CONFIG_DEFAULTS.showGroupSummary).description('在分组标题后汇总调用次数与最近调用时间。'),\n  statsWindowDays: z.number().min(0).max(3650).default(HUB_CONFIG_DEFAULTS.statsWindowDays).description('只统计最近 N 天的使用次数；0 = 全部历史。'),\n  statsScanMinutes: z.number().min(1).max(1440).default(HUB_CONFIG_DEFAULTS.statsScanMinutes).description('后台扫描会话日志的间隔（分钟，最小 1）。'),\n  githubToken: z.string().role('secret').description('市场/来源走 GitHub API：匿名每小时 60 次，填 token 后 5000 次。留空即匿名（或跟随 GITHUB_TOKEN 环境变量）。'),\n}\n\n/**\n * The live plugin config the settings page edits. Field order here is the row\n * order the auto-generated page renders.\n */\nexport const Config = z.object({\n  enabled: ConfigFields.enabled.volatile(),\n  announceToAgent: ConfigFields.announceToAgent.volatile(),\n  dotModelColor: ConfigFields.dotModelColor.volatile(),\n  dotUserColor: ConfigFields.dotUserColor.volatile(),\n  showUseCount: ConfigFields.showUseCount.volatile(),\n  showUseTime: ConfigFields.showUseTime.volatile(),\n  showGroupSummary: ConfigFields.showGroupSummary.volatile(),\n  statsWindowDays: ConfigFields.statsWindowDays.volatile(),\n  statsScanMinutes: ConfigFields.statsScanMinutes.volatile(),\n  githubToken: ConfigFields.githubToken.volatile(),\n})\n\n/**\n * The settings namespace this plugin's config lives under, narrowed to the\n * settings package's branded type. The browser half resolves the same form\n * through `ctx.configForms.get(HUB_ENTRY_ID)`.\n */\nexport const ENTRY_ID = HUB_ENTRY_ID as SettingsNamespace\n\n/** Every config field, in the order the settings page renders them (used to walk the volatile refs). */\nconst CONFIG_FIELDS = [\n  'enabled',\n  'announceToAgent',\n  'dotModelColor',\n  'dotUserColor',\n  'showUseCount',\n  'showUseTime',\n  'showGroupSummary',\n  'statsWindowDays',\n  'statsScanMinutes',\n  'githubToken',\n] as const\n\n/** Order of the announcement section within the tool-guidance band. */\nconst SECTION_ORDER = 152\n\n/**\n * Register the hub's provider once more into every live agent's own skill\n * layer, and keep following agents as they come and go.\n *\n * Why a second registration is REQUIRED for invocation overrides: an agent's\n * skill catalog comes from the preset layer's own filesystem provider, which\n * is nearer than the global layer. dsh-skill merges layers in order and the\n * LAST write of a duplicate name wins, so a global-layer override can never\n * outrank it — the override entry must exist in a layer nearer than the\n * preset's. Registering the same shared instance per agent does exactly that\n * (the shared instance keeps a single watch timer; only the per-layer\n * controls differ, and each control invalidates its own layer's cache).\n *\n * Everything is defensive: the host may expose none of `ctx.on` / `ctx.get`,\n * an agent may carry no skills service, and the event names may change —\n * in every case this degrades to \"no agent-layer override\" (the global\n * catalog still applies it) instead of breaking the plugin load.\n */\nfunction registerAgentSkillPolicy(\n  ctx: Context,\n  ensureProvider: (control: SkillProviderControl) => SkillHubProvider,\n): () => void {\n  interface AgentLike {\n    id?: unknown\n    ctx?: unknown\n  }\n  type AgentEvent = { agent?: AgentLike }\n  type SkillsLike = { registerProvider?: (factory: (control: SkillProviderControl) => SkillHubProvider) => (() => void) | undefined }\n  const host = ctx as unknown as {\n    on?: (event: string, listener: (payload: AgentEvent) => void) => (() => void) | undefined\n    get?: (key: string) => unknown\n  }\n  if (typeof host.on !== 'function') {\n    ctx.logger.warn('[dsh-skill-hub] ctx.on unavailable: agent-layer invocation overrides are disabled (global catalog still applies them)')\n    return () => {}\n  }\n  const disposers = new Map<string, () => void>()\n\n  const install = (agent: AgentLike | undefined): void => {\n    if (agent === undefined || typeof agent.id !== 'string' || disposers.has(agent.id)) return\n    const agentCtx = agent.ctx as { get?: (key: string) => unknown; skills?: unknown } | undefined\n    const skills = (agentCtx !== undefined && typeof agentCtx.get === 'function'\n      ? agentCtx.get('skills')\n      : agentCtx?.skills) as SkillsLike | undefined\n    if (skills === undefined || typeof skills.registerProvider !== 'function') {\n      ctx.logger.warn('[dsh-skill-hub] agent layer has no skills service; skipping agent-layer registration for ' + String(agent.id))\n      return\n    }\n    const dispose = skills.registerProvider((control) => ensureProvider(control))\n    if (dispose !== undefined) {\n      disposers.set(agent.id, dispose)\n      ctx.logger.info('[dsh-skill-hub] invocation-override provider registered into agent layer ' + agent.id)\n    }\n  }\n  const uninstall = (agent: AgentLike | undefined): void => {\n    if (agent === undefined || typeof agent.id !== 'string') return\n    const dispose = disposers.get(agent.id)\n    disposers.delete(agent.id)\n    if (dispose !== undefined) dispose()\n  }\n\n  const stopCreated = host.on('agent/created', (payload) => install(payload.agent))\n  const stopDisposed = host.on('agent/disposed', (payload) => uninstall(payload.agent))\n  const agents = typeof host.get === 'function' ? host.get('agents') : undefined\n  if (agents !== undefined && typeof (agents as { list?: unknown }).list === 'function') {\n    for (const agent of (agents as { list: () => AgentLike[] }).list()) install(agent)\n  }\n\n  return () => {\n    if (stopCreated !== undefined) stopCreated()\n    if (stopDisposed !== undefined) stopDisposed()\n    for (const dispose of disposers.values()) dispose()\n    disposers.clear()\n  }\n}\n\n/** Model-facing announcement: plugin presence, capabilities, and limits. */\nexport const SKILL_HUB_GUIDANCE = [\n  '本机已安装 dsh-skill-hub 插件（DSH Web GUI 技能中枢）：设置 →「技能中枢」分区为管理主页（通用 / 工作区 / 市场 / 回收站四个 tab，同一面板也作为 960px 侧栏入口挂在侧边栏「插件」区）；本插件的配置页（启用/公告开关、圆点颜色、GitHub token、统计窗口）在插件管理页——侧边栏「插件」→ 本插件，是本插件自己注册的配置卡片（默认折叠，点标题展开）。能力：完整本地技能目录（项目/自定义/用户/内置全部来源，走官方 ctx.skills 注册表，含第三方 provider）；按来源（上游仓库）、按目录（发现目录，每个根一张卡、可整目录启停）与自定义角色浏览，分组/来源头部的滑动开关可一键启用/禁用整组（跨组冲突时询问）；角色支持「切换」—— 启用成员、停用其余可切换技能（弹窗内可勾选保留，默认全停用），切换前状态留存、可一键还原（角色视图始终展示完整名单，不受来源/状态筛选影响，搜索与调用方式仍生效）；市场：内置市场目录（精选仓库一键添加）加自定义仓库源，扫描后勾选安装，每个市场源行显示已装/可更新/上游已删数量，支持「检查全部」与「全部更新」；skills.sh 索引搜索（按技能名搜，结果显示仓库与安装次数，可选「安装」直装单个技能——不跟踪上游更新，或「加为源」登记仓库后扫描）；来源跟踪：从 GitHub 仓库（市场源或直接地址）导入的技能记录上游 repo/commit 快照，可检查更新、选择同步、上游删除时跟进删除（移入回收站 tab，可恢复，恢复后保留来源与角色归属）；个人技能（无来源记录）不跟踪；调用次数与最近使用时间统计；查看技能正文；发现诊断；内容审计（隐藏字符、危险命令、凭据路径与体积上限；市场导入命中阻断级规则即整包拒绝）；技能目录公告预算（一层渐进加载注入的字符数与 token 估算）；本地内容哈希比对（标出被自己改过、同步会覆盖的技能）；从其他 agent 的技能目录只读导入（Claude Code / Codex / WorkBuddy / Cursor / Gemini CLI 等；同一份文件挂在多个 agent 目录时合并为一条；用户级收进 ~/.dsh/skills，项目级——即 <项目根>/.claude/skills 之类——收进该项目的 .dsh/skills）；从 ZIP 包导入（包内每个含 SKILL.md 的目录算一个技能，逐个过内容审计，路径穿越/符号链接/加密包/解压炸弹在解压前拦截）；新建技能向导（写入 ~/.dsh/skills 或 ~/.agents/skills）。限制：仅用户级技能（user-dsh/user-agents 根目录）可写可删；所有可开关的技能（含用户级、项目级、外部 provider 只读技能）停用都只写 sidecar 策略（关闭模型自动调用，「/技能名」仍可用，源文件一个字节不动）、内置/运行时技能只读展示；路由受 dsh 自身的 /api 信任栅栏保护（回环、监听器绑定地址、--trusted-host 声明的 authority，外加浏览器会话认证），因此反代部署下与 GUI 同一套放行规则。用户提到「技能管理 / 技能列表 / 技能开关 / 技能同步 / 技能市场 / 更新技能 / 新建技能」时即指本插件，请据此协作。',\n  'The dsh-skill-hub plugin is installed (the DSH Web GUI skill hub): Settings → \"Skills Hub\" is the management page (General / Workspace / Market / Trash tabs; the same panel also mounts as a 960px sidebar entry under the Plugins area of the left rail); the plugin\\'s configuration page (enable / announcement toggles, dot colors, GitHub token, stats window) is registered by the plugin itself on its own page in the Plugins manager (sidebar → 插件 → the plugin; collapsed until you expand the title). Capabilities: full local skill catalog (project / custom / user / bundled roots via the official ctx.skills registry, including third-party providers); browsing by source (upstream repo), location (discovery root) and custom roles, each group header carrying a sliding switch to enable/disable the whole group in one click (cross-group conflicts prompt the user); a role can be \"switched to\" — enable its members, pause every other switchable skill, with the previous states saved for a one-click restore; market: a built-in catalog of curated repos (one-click add) plus custom repo sources, scan-and-install import, per-source installed / updatable / deleted-upstream badges with \"check all\" and \"update all\" actions; skills.sh index search (search by skill name; results show the hosting repo and install count, with either Install — pulls that one skill in without upstream tracking — or Add source — registers the repo and scans it); upstream source tracking: skills imported from GitHub repos (market sources or direct URLs) record the repo/commit snapshot, support update checks, selective sync, and follow-up deletion when the upstream removes a skill (moves it into the Trash tab, restorable with its source and role membership intact); personal skills (no source record) are never tracked; invocation counts and last-used times; skill body inspection; discovery diagnostics plus a content audit (hidden characters, dangerous commands, credential paths, size caps — a market import with a blocking finding is refused as a whole); the skill-catalog announcement budget (characters and estimated tokens for the first progressive-disclosure layer); local content-hash comparison (flags skills you edited that a sync would overwrite); read-only import from other agents\\' skill folders (Claude Code / Codex / WorkBuddy / Cursor / Gemini CLI and friends; one file symlinked into several agent folders is merged into a single row; user-level into ~/.dsh/skills, project-level — i.e. <projectRoot>/.claude/skills and friends — into that project\\'s .dsh/skills); import from a ZIP archive (every directory holding a SKILL.md becomes one skill, each audited, with path traversal / symlinks / encrypted archives / decompression bombs rejected before unpacking); new-skill wizard (writes to ~/.dsh/skills or ~/.agents/skills). Limits: only user-level skills (user-dsh/user-agents roots) are writable; every toggleable skill (user-level, project and external read-only providers alike) is paused through a sidecar policy (off = model invocation switched off while \"/name\" keeps working, no source file is renamed or edited); bundled/runtime skills are read-only; the routes sit behind dsh\\'s own /api trust fence (loopback, the listener\\'s bind address, any --trusted-host authority, plus browser-session authentication), so a reverse-proxied deployment is judged exactly like the GUI around it. When the user mentions \"skill management / skill list / skill toggle / skill sync / skill market / update skills / new skill\", this plugin is what they mean — collaborate accordingly.'\n].join('\\n\\n')\n\n/**\n * Mount the skill hub routes and announcement.\n * @param ctx - host plugin context carrying webServer/skills/systemPrompt/settings.\n */\nexport function apply(ctx: Context, config?: Config): void {\n  /**\n   * Read the runtime config out of our own volatile config refs.\n   *\n   * This is the whole point of `volatile()`: the Loader updates those values\n   * **in place** (`ConfigEditor.edit` → `resolveConfig(fiber.runtime, next)` →\n   * `updateVolatile`) without rebuilding the fiber, so a held reference always\n   * answers `.get()` with the current value. Consequences worth remembering:\n   *   - no `settings.describe()` per request (it walks and projects every entry\n   *     in the profile — the reason this used to be slow);\n   *   - no subscription or watcher is needed for *reading*;\n   *   - the plugin keeps working when the Settings service is absent\n   *     (issue #11: business logic must not depend on Settings).\n   */\n  const readConfig = (): Partial<HubConfig> => {\n    const out: Record<string, unknown> = {}\n    for (const field of CONFIG_FIELDS) {\n      const ref = (config as unknown as Record<string, { get?: () => unknown } | undefined> | undefined)?.[field]\n      const value = ref !== undefined && typeof ref.get === 'function' ? ref.get() : ref\n      if (value !== undefined) out[field] = value\n    }\n    return out as Partial<HubConfig>\n  }\n  const current = (): HubConfig => resolveHubConfig(readConfig())\n\n  /** The Settings service, when this deployment mounts it. Absent ⇒ no user layer to read or write. */\n  const settingsOf = (): SettingsForms | undefined => ctx.get('settings') as SettingsForms | undefined\n\n  const store = new SkillHubStore()\n  let disposeRoutes: (() => void) | undefined\n  let disposeSection: (() => void) | undefined\n  // The hub's own provider contributes user/project skills to the registry's\n  // GLOBAL layer — the web app deliberately keeps that layer empty (presets\n  // own per-scope discovery), and the GUI needs a session-independent view.\n  let disposeProvider: (() => void) | undefined\n  // The SAME provider instance is registered once more into every live agent's\n  // own skill layer (nearer than the preset layer) so an invocation override\n  // can outrank the preset's native filesystem provider — see\n  // registerAgentSkillPolicy below.\n  let disposeAgentProviders: (() => void) | undefined\n  let providerInstance: SkillHubProvider | undefined\n  /** One control per skill layer (global + each live agent): an override change must invalidate all of them. */\n  const providerControls = new Set<SkillProviderControl>()\n  // Optional invocation-count source; only set once a session-query service\n  // is present (see the soft inject below). Absent deployments just omit the\n  // stats route's data rather than failing to load.\n  let stats: SkillStatsReader | undefined\n\n  // The raw saved config layer (fields the user explicitly overrode); the\n  // config route reports it so callers can mark overridden fields. Empty when\n  // the deployment has no Settings service — the plugin still runs.\n  const saved = (): Partial<HubConfig> => {\n    const descriptor = settingsOf()?.describe().find((entry) => entry.ns === ENTRY_ID)\n    return (descriptor?.user as Partial<HubConfig> | undefined) ?? {}\n  }\n\n  // Persist a config patch through the settings transport. A patch value of\n  // undefined clears the saved override — expressed as a path `unset`, which\n  // makes the field fall back to its inherited value instead of writing a\n  // literal undefined (the old sidecar's reset semantics). The write reloads\n  // this Loader entry, so apply() re-runs and re-syncs every surface below.\n  const updateConfig = async (patch: Partial<HubConfig>): Promise<HubConfig> => {\n    const ops: SettingsPathOp[] = []\n    for (const [field, value] of Object.entries(patch)) {\n      if (value === undefined) ops.push({ op: 'unset', path: [field] })\n      else ops.push({ op: 'set', path: [field], value })\n    }\n    const settings = settingsOf()\n    if (settings === undefined) throw new Error('this deployment does not mount the settings service; config is read-only')\n    if (ops.length > 0) {\n      await settings.mutate(ENTRY_ID, ops)\n      // A settings write updates this entry's values in place WITHOUT\n      // re-entering apply() (see `current`), so the section / provider / routes\n      // registered from the old values would otherwise keep serving them until\n      // a restart. Re-evaluate here, where we know the write landed.\n      sync()\n    }\n    return current()\n  }\n\n  // Register (or drop) every surface to match the current config. Each\n  // group is kept under one disposer: re-registering first tears the old\n  // one down so duplicate-name registrations never throw. The route family\n  // (including the config route) stays mounted even with the master switch\n  // off so the settings card can always read and re-enable the hub; the\n  // business routes answer 503 while disabled.\n  /**\n   * Whether this plugin's fiber is still mounted.\n   *\n   * Async work started from `apply()` — the stats wiring and the persistence\n   * probe — can settle after the fiber unloaded: a config rewrite reloads the\n   * plugin, and disable/enable tears it down. Service reads on an inactive\n   * context throw instead of returning undefined, so every continuation\n   * re-checks this before touching `ctx` (issue #19: a cold-start abort with\n   * `cannot get required service \"systemPrompt\" in inactive context`).\n   *\n   * The generation counters cannot cover this: they only invalidate a build\n   * superseded by a *newer* build, and teardown does not bump them.\n   */\n  const mounted = (): boolean => {\n    // `fiber` has always been public on a Cordis context, but stay tolerant of\n    // a host whose Cordis predates it: absent means \"we cannot tell\", and the\n    // pre-#19 behaviour is the safer answer there.\n    const fiber = (ctx as { fiber?: { uid: number | null } }).fiber\n    return fiber === undefined || fiber.uid !== null\n  }\n\n  /** Logger for continuations that may outlive the fiber (#19). */\n  const logInfo = (message: string): void => {\n    if (mounted()) ctx.logger.info(message)\n  }\n  const logWarn = (message: string, error?: unknown): void => {\n    if (!mounted()) return\n    if (error === undefined) ctx.logger.warn(message)\n    else ctx.logger.warn(message, error)\n  }\n\n  const sync = (): void => {\n    // A late stats continuation may still reach here after teardown (#19).\n    if (!mounted()) return\n    if (disposeSection !== undefined) {\n      disposeSection()\n      disposeSection = undefined\n    }\n    if (disposeProvider !== undefined) {\n      disposeProvider()\n      disposeProvider = undefined\n    }\n    if (disposeAgentProviders !== undefined) {\n      disposeAgentProviders()\n      disposeAgentProviders = undefined\n    }\n    providerInstance = undefined\n    const value = current()\n    // GitHub auth for market/source API calls: env GITHUB_TOKEN/GH_TOKEN is the\n    // fallback (read at module load); an explicit settings value wins and is\n    // applied by re-running this sync from updateConfig after the write lands.\n    setGithubToken(value.githubToken)\n    if (value.announceToAgent) {\n      disposeSection = ctx.systemPrompt.section({\n        name: 'plugin:dsh-skill-hub',\n        order: SECTION_ORDER,\n        text: SKILL_HUB_GUIDANCE,\n      })\n    }\n    if (value.enabled) {\n      // registerProvider returns the exact cordis effect disposer: the fiber\n      // unregisters the provider and invalidates catalog caches on teardown.\n      providerControls.clear()\n      providerInstance = undefined\n      const overrides = async (): Promise<ReadonlySet<string>> => new Set(await store.listInvocationOverrides())\n      // 惰性创建：global 与各 agent 层的 factory 共享同一实例（watch 定时器\n      // 只起一个），但每个注册的 control 都收进集合 —— override 变化必须\n      // 让所有层的缓存一起失效，只刷 global 会让 agent 视角仍旧看到旧状态。\n      const ensureProvider = (control: SkillProviderControl): SkillHubProvider => {\n        providerControls.add(control)\n        if (providerInstance === undefined) {\n          providerInstance = new SkillHubProvider(control, dshHome(), overrides)\n        }\n        return providerInstance\n      }\n      disposeProvider = ctx.effect(\n        () => ctx.skills.registerProvider((control) => ensureProvider(control)),\n        'dsh-skill-hub: provider',\n      )\n      disposeAgentProviders = registerAgentSkillPolicy(ctx, ensureProvider)\n    }\n    ctx.logger.info(`[dsh-skill-hub] surfaces synced: enabled=${value.enabled} announceToAgent=${value.announceToAgent}`)\n    if (disposeRoutes !== undefined) {\n      disposeRoutes()\n      disposeRoutes = undefined\n    }\n    disposeRoutes = ctx.effect(\n      () => {\n        const disposers = makeRoutes({\n          skills: ctx.skills,\n          store,\n          // The host's own `/api` trust fence (loopback ∪ bind address ∪\n          // --trusted-host ∪ browser session). Read per request: Connection\n          // may be provided after this plugin starts, and a one-shot read here\n          // would latch the literal-loopback fallback for the whole process.\n          // A *persistent* absence means the upstream composition changed —\n          // say so once instead of silently re-creating issue #17.\n          fence: hostTrustFence(\n            () => ctx.get('connection'),\n            () => ctx.logger.warn('[dsh-skill-hub] Connection service absent: routes fall back to literal-loopback; reverse-proxy deployments will 403 until it mounts'),\n          ),\n          invalidate: () => {\n            for (const control of providerControls) control.invalidate()\n          },\n          stats,\n          config: current,\n          saved,\n          updateConfig,\n        }).map((route) => ctx.webServer.register(route))\n        return () => {\n          for (const dispose of disposers) dispose()\n        }\n      },\n      'dsh-skill-hub: routes',\n    )\n  }\n\n  // Initial registration from the composition entry. Later changes — the\n  // settings page, the config route, the Host document editor — rewrite this\n  // Loader entry, which re-enters apply(), so no in-process watcher is needed.\n  sync()\n\n  // One-time migration: an install upgraded from the sidecar-configured\n  // build seeds the settings namespace from the saved sidecar config when the\n  // namespace has no user section yet. Later edits live only in the settings\n  // document; the sidecar keeps its (now-stale) copy untouched.\n  // Startup: 清理 Issue #3 遗留的 .*.import-* 临时目录（尽早回收，不阻塞）\n  void (async () => {\n    const home = dshHome()\n    const agentsHome = process.env.DSH_AGENTS_HOME ?? join(homedir(), '.agents')\n    for (const root of [join(home, 'skills'), join(agentsHome, 'skills')]) {\n      try {\n        const c = await cleanupLeftoverImportDirs(root)\n        if (c > 0) logInfo(`[dsh-skill-hub] startup cleaned ${c} leftover import temp dir(s) in ${root}`)\n      } catch (error) {\n        logWarn('[dsh-skill-hub] startup cleanup failed', error)\n      }\n    }\n    // 一次性迁移：旧版本靠把 SKILL.md 改名成 SKILL.md.disabled 来停用，新版\n    // 改成写策略、文件不动。必须最先跑，否则老用户升级后停用技能会全部复活。\n    try {\n      const migrated = await migrateRenamedDisabledSkills(store, home)\n      if (migrated.length > 0) logInfo(`[dsh-skill-hub] startup migrated ${migrated.length} renamed disabled skill(s) to policy overrides`)\n    } catch (error) {\n      logWarn('[dsh-skill-hub] startup disabled-skill migration failed', error)\n    }\n    // 对账：迁移后处理残留的 .disabled、sidecar 缺记录等历史情况。\n    try {\n      const reconciled = await reconcileDisabledSkills(store, home)\n      if (reconciled.length > 0) {\n        logInfo(`[dsh-skill-hub] startup reconciled ${reconciled.length} disabled skill record(s): ${reconciled.map((entry) => entry.name).join(', ')}`)\n      }\n    } catch (error) {\n      logWarn('[dsh-skill-hub] startup disabled-skill reconcile failed', error)\n    }\n    // 反向对账：记录还在、文件已不在 → 修路径或删记录。不做这一步，那条记录会\n    // 把名字永久锁死（启用/新建/删除三条路都失败）。\n    try {\n      const pruned = await pruneStaleDisabledSkills(store, home)\n      if (pruned.repaired.length > 0 || pruned.removed.length > 0) {\n        logInfo(`[dsh-skill-hub] startup pruned disabled records: repaired ${pruned.repaired.length} (${pruned.repaired.map((entry) => entry.name).join(', ') || '-'}), removed ${pruned.removed.length} (${pruned.removed.join(', ') || '-'})`)\n      }\n    } catch (error) {\n      logWarn('[dsh-skill-hub] startup disabled-record prune failed', error)\n    }\n  })()\n\n  void (async () => {\n    try {\n      const legacy = await store.getConfig()\n      // The read is awaited; the plugin may have unloaded meanwhile (#19).\n      if (!mounted()) return\n      if (Object.keys(legacy).length > 0 && Object.keys(saved()).length === 0) {\n        const settings = settingsOf()\n        if (settings !== undefined) await settings.update(ENTRY_ID, legacy as Record<string, unknown>)\n      }\n    } catch (error) {\n      logWarn('[dsh-skill-hub] sidecar config migration into the settings namespace failed', error)\n    }\n  })()\n\n  // Optional trigger statistics: while a session-query service exists, wire a\n  // cached invocation-count reader into the stats route. Re-running sync()\n  // re-registers the routes with the reader attached (mirrors the optional\n  // stats wiring — no sessionQuery service ever mounted means none of this\n  // runs).\n  //\n  // Read-path preference: the host's sessionPersistence seam serves raw stored\n  // logs (decompress + parse only — no Session restore/validation, the host\n  // cost that OOMed large histories, see issue #7), with the query seam\n  // covering live sessions. Without a persistence service the reader falls\n  // back to sequential query reads. Scans are strictly lazy: the first one\n  // starts on the panel's first /stats poll, never at plugin startup (a\n  // headless boot with no browser must not pay for statistics nobody reads).\n  //\n  // Mount ordering between the two host services is not guaranteed, so the\n  // reader is (re-)built generation-guarded: a query-only reader wires\n  // immediately, and a later-arriving persistence service upgrades it to the\n  // cold path. A superseded build never assigns.\n  let statsQuery: SessionQueryLike | undefined\n  let statsPersistence: SessionPersistenceLike | undefined\n  let statsGeneration = 0\n  const wireStats = (): void => {\n    const query = statsQuery\n    if (query === undefined) return\n    const generation = ++statsGeneration\n    const cold = statsPersistence\n    void (async () => {\n      // 恢复 sidecar 里的增量扫描检查点后再建 reader（异步、不阻塞）：\n      // 重启后无需重新解压全部历史日志；每次扫描完都落盘（含上次总数），所以\n      // 重启后面板秒出旧数、后台重扫。扫描间隔与滚动窗口都从设置命名空间\n      // 实时读取——卡片里改完即生效，无需重启。\n      const checkpoint = await store.getSkillStatsState().catch(() => undefined)\n      if (generation !== statsGeneration || !mounted()) return\n      const scanMinutes = (): number => {\n        const value = current().statsScanMinutes\n        return typeof value === 'number' && value >= 1 ? Math.floor(value) : HUB_CONFIG_DEFAULTS.statsScanMinutes\n      }\n      const windowDays = (): number => {\n        const value = current().statsWindowDays\n        return typeof value === 'number' && value >= 0 ? Math.floor(value) : HUB_CONFIG_DEFAULTS.statsWindowDays\n      }\n      const reader = createSkillStatsReader(query, () => scanMinutes() * 60_000, {\n        checkpoint,\n        windowDays,\n        ...(cold === undefined ? {} : {\n          persistence: cold,\n          listLiveIds: async () => {\n            try {\n              const records = await query.listSessions()\n              return records.filter((record) => (record as { live?: unknown }).live === true).map((record) => record.header.id)\n            } catch {\n              return []\n            }\n          },\n          readLiveSession: async (id) => {\n            try {\n              return { events: (await query.readSession(id)).events }\n            } catch {\n              return undefined\n            }\n          },\n        }),\n        onCheckpoint: (next) => {\n          void store.saveSkillStatsState(next).catch((error) => {\n            if (mounted()) ctx.logger.warn('[dsh-skill-hub] persisting skill-stats checkpoint failed', error)\n          })\n        },\n      })\n      if (generation !== statsGeneration || !mounted()) return\n      ctx.logger.info(`[dsh-skill-hub] stats seam: ${cold === undefined ? 'session-query (fallback)' : 'session-persistence (cold)'}`)\n      stats = reader\n      sync()\n    })()\n  }\n  ctx.inject(['sessionQuery'], (sctx) => {\n    statsQuery = sctx.sessionQuery\n    wireStats()\n    // The persistence service may mount after the query service: upgrade the\n    // reader when it arrives (no-op when it never does).\n    sctx.inject(['sessionPersistence'] as unknown as ['sessionQuery'], (pctx) => {\n      void (async () => {\n        const raw = (pctx as unknown as { sessionPersistence?: unknown }).sessionPersistence\n        const seam = asPersistenceSeam(raw)\n        if (seam === undefined) {\n          if (mounted()) ctx.logger.warn('[dsh-skill-hub] sessionPersistence shape mismatch, staying on query fallback')\n          return\n        }\n        try {\n          await seam.list() // probe: headers only, must succeed before trusting the cold path\n        } catch (error) {\n          if (mounted()) ctx.logger.warn('[dsh-skill-hub] persistence seam probe failed, staying on query fallback', error)\n          return\n        }\n        // The probe is awaited, so the plugin may have unloaded meanwhile (#19).\n        if (!mounted()) return\n        statsPersistence = seam\n        wireStats()\n      })()\n    })\n  })\n}\n"
    },
    {
      "path": "src/client/index.tsx",
      "content": "/**\n * Browser-half entry for the dsh-skill-hub plugin — runs inside the dsh\n * web GUI.\n *\n * Registers the dsh-skill-hub locale dictionaries and mounts:\n *  - a top-level Settings section (Settings → 技能中枢) hosting the skill hub\n *    panel: catalog, search, enable/disable, diagnostics, new-skill form;\n *  - the chat \"/\" menu skill dots, colored from the same config the panel reads.\n *\n *  - a configuration card in the `plugins.bundle.config` slot, keyed by the\n *    BUNDLE PACKAGE NAME, rendered on the plugin's own page in the Plugins\n *    manager (sidebar → 插件 → dsh-skill-hub). dsh 0.1.7 has no auto-generated\n *    config page: the manager only renders that section for bundles that\n *    register this slot, and the card writes through the shared config form\n *    (`ctx.configForms.get(skill-hub)`), the same form the host routes read.\n *\n * Failure policy: mounting problems are logged, never thrown — the web\n * shell fails the whole boot when a plugin apply throws, and an external\n * plugin must not take the GUI down.\n *\n * Export discipline (packages/client rule): the /client surface carries\n * what cordis loading needs plus types only — all value exports stay\n * internal.\n */\n\nimport type { Context as ClientContext } from '@deepseek-ai/cordis'\n// Type-only: pulls the locale plugin's Context merge (ctx.locale).\nimport type {} from '@deepseek-ai/dsh-client-locale/client'\n// Type-only: pulls the configForms service merge and the settings.section slot.\nimport type {} from '@deepseek-ai/dsh-client-ui-settings/client'\n// Type-only: pulls the LocaleNamespaceMap merge table.\nimport type {} from '@deepseek-ai/dsh-client-ui-slots'\n// Type-only: pulls the Context merge for ctx.inputTriggers (slash-dots wiring).\nimport type {} from '@deepseek-ai/dsh-client-ui-input-trigger/client'\n// Type-only: pulls the plugin-manager SlotMap merge (plugins.bundle.config).\nimport type {} from '@deepseek-ai/dsh-client-ui-plugin-manager/client'\n// Type-only: pulls the connection/reset event.\nimport type {} from '@deepseek-ai/dsh-client-connection/client'\n\n// The slots service is owned by ui-renderer, which this build does not depend\n// on; augment the Context locally so the browser half typechecks.\ndeclare module '@deepseek-ai/cordis' {\n  interface Context {\n    slots: any\n  }\n}\nimport { HUB_ENTRY_ID, type HubSettingsValue } from '../protocol.ts'\nimport { SkillHubApi } from './api.ts'\nimport { en, zh, type HubKey } from './locales.ts'\nimport { applySettingsNavIcon } from './settings-nav-icon.ts'\nimport { setupSkillSlashDots } from './slash-dots.tsx'\nimport { SkillHubSettingsCard, SkillHubSettingsCardController } from './SkillHubSettingsCard.tsx'\nimport { SkillHubPanel } from './panel/SkillHubPanel.tsx'\nimport { IconSkillOutline16 } from './icons.tsx'\n\n/** Locale namespace this plugin owns. */\nconst NS = 'dsh-skill-hub'\n\ndeclare module '@deepseek-ai/dsh-client-ui-slots' {\n  interface LocaleNamespaceMap {\n    /** dsh-skill-hub surface copy. */\n    'dsh-skill-hub': HubKey\n  }\n}\n\n/**\n * Required services (fiber inject waiting — the runtime must be up first).\n * `connection`/`remote` are the settings transport's own prerequisites\n * (`ctx.configForms.get` resolves them on the caller's fiber), and\n * `configForms` is the shared settings-form service itself; mirror the\n * official settings-plugins inject list.\n */\nexport const inject = ['slots', 'locale', 'connection', 'remote', 'configForms', 'inputTriggers']\n\n/** Type-only surface (export discipline: no value exports beyond the plugin contract). */\nexport type { SkillHubPanelProps } from './panel/SkillHubPanel.tsx'\nexport type { SkillHubSettingsState } from './SkillHubSettingsCard.tsx'\nexport type { HubKey } from './locales.ts'\n\n/**\n * Mount the settings card and the skill hub section.\n * @param ctx - client root context (slots, locale).\n */\nexport function apply(ctx: ClientContext): void {\n  ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'dsh-skill-hub: dictionaries')\n  const t = ctx.locale.bind(NS)\n  const api = new SkillHubApi()\n\n  // The hub's config form is the same Loader entry the host writes and the\n  // Plugins manager renders; the browser half reads it only to color the dots\n  // (single form instance, so slash-dots keeps one subscription).\n  const scope = ctx.configForms.get<HubSettingsValue>(HUB_ENTRY_ID)\n  const settingsCard = new SkillHubSettingsCardController(scope)\n\n  // Chat `/` 菜单技能圆点：为每个候选行加可调用性圆点（蓝=模型可调，绿=仅用户），颜色与面板图例同步；仅装饰，不自动预填 \"/\"\n  // inject 含 inputTriggers 保证 fiber 就绪后再 wrap，slash-dots 内的 undefined 防御仅用于单元测试 mock\n  ctx.effect(() => setupSkillSlashDots(ctx, api, scope), 'dsh-skill-hub: slash dots')\n\n  // The plugin's own configuration page. It must be registered here: the\n  // Plugins manager only renders the config section for bundles that appear in\n  // `plugins.bundle.config` (`ledger.bundles.has(openPkg.name)`), and its key is\n  // the BUNDLE PACKAGE NAME — not the settings entry id (`skill-hub`). There is\n  // no auto-generated fallback page in dsh 0.1.7.\n  ctx.effect(\n    () => ctx.slots.inject('plugins.bundle.config', () => ctx.slots.register({\n      name: 'plugins.bundle.config',\n      key: 'dsh-skill-hub',\n      locale: NS,\n      inject: () => settingsCard.inject(),\n    }, SkillHubSettingsCard)),\n    'dsh-skill-hub: plugin config',\n  )\n\n  // Top-level Settings section: the skill management page.\n  ctx.effect(\n    () => ctx.slots.inject('settings.section', () => ctx.slots.register({\n      name: 'settings.section',\n      id: 'skill-hub',\n      order: 12,\n      label: () => t('entry.label'),\n      locale: NS,\n      inject: () => ({}),\n    }, () => <SkillHubPanel api={api} />)),\n    'dsh-skill-hub: settings section',\n  )\n\n  // Wide sidebar main panel: same hub surface, 960px shell. The settings page\n  // remains the canonical place for configuration; this panel is the sidebar\n  // companion for browsing skills without leaving the conversation.\n  ctx.effect(\n    () => ctx.slots.inject('main', () => ctx.slots.register({\n      name: 'main',\n      key: 'skill-hub',\n      locale: NS,\n      inject: () => ({}),\n    }, () => <SkillHubPanel api={api} mode='sidebar' />)),\n    'dsh-skill-hub: sidebar main panel',\n  )\n\n  // Sidebar entry icon, directly under 插件 in the left rail.\n  ctx.effect(\n    () => ctx.slots.inject('sidebar.panellist', () => ctx.slots.register({\n      name: 'sidebar.panellist',\n      id: 'skill-hub',\n      order: 30,\n      label: () => t('entry.label'),\n      locale: NS,\n    }, IconSkillOutline16)),\n    'dsh-skill-hub: sidebar entry',\n  )\n\n  // Host shell has no section-icon registration; keep the nav gear swapped for the skill icon.\n  ctx.effect(() => applySettingsNavIcon(), 'dsh-skill-hub: settings nav icon')\n}\n"
    },
    {
      "path": "src/routes.ts",
      "content": "/**\n * The /api/skill-hub route family: full catalog (enabled skills from the\n * official registry + hub-disabled skills + discovery diagnostics), skill\n * detail, enable/disable toggle, new-skill scaffold, user groups (tags +\n * origin collections), and upstream source tracking (check/sync/follow\n * upstream deletion into a restorable trash). Every route carries the host's\n * own `/api` trust fence (loopback, the listener's bind address, each\n * `--trusted-host` authority, then the browser session) — these endpoints\n * rename files under the user's skill roots, so they must never be laxer than\n * the GUI around them (issue #17).\n *\n * 按域拆分后的聚合入口：各域 handler 在 ./routes/<domain>.ts，共享围栏在\n * ./routes/helpers.ts，节流/任务状态在 ./routes/route-state.ts。\n * 老 `from './routes.ts'`（makeRoutes + SkillHubRouteDeps）保持可用。\n */\n\nimport type { HostConnectionHandle } from '@deepseek-ai/dsh-client-connection'\nimport type { WebRoute } from '@deepseek-ai/dsh-host-webserver'\nimport { SKILL_HUB_API_ROOT } from './protocol.ts'\nimport { createRoute, writeError, type SkillHubRouteDeps } from './routes/helpers.ts'\nimport { loopbackOnlyFence, type RouteFence } from './routes/http.ts'\nimport { catalogRoutes } from './routes/catalog.ts'\nimport { configRoutes } from './routes/config.ts'\nimport { marketRoutes } from './routes/market.ts'\nimport { repoImportRoutes } from './routes/repo-import.ts'\nimport { groupRoutes } from './routes/groups.ts'\nimport { sourceRoutes } from './routes/sources.ts'\nimport { foreignRoutes } from './routes/foreign.ts'\nimport { zipImportRoutes } from './routes/zip-import.ts'\n\nexport type { SkillHubRouteDeps, SkillLookupLike } from './routes/helpers.ts'\nexport type { RouteFence } from './routes/http.ts'\n\n/**\n * Build the family's trust fence from the host's `/api` model.\n *\n * `ctx.connection.requestRejection` is the documented hook for fencing another\n * Web route; with no Connection service (a webserver-only composition, or a\n * unit test) the literal-loopback check stands in, so the fallback is the old\n * behaviour rather than an open route family.\n *\n * The service is read **per request**, not once at mount: plugins start in\n * composition order, so a one-shot read at `apply()` time would latch the\n * fallback whenever this plugin happens to come up before Connection. A\n * persistent absence is almost certainly an upstream composition change rather\n * than a transient startup order, so the first miss fires `onMissing` once —\n * without that signal the fallback would silently reproduce issue #17 after\n * any future upstream rename of the service.\n * @param read - resolves `ctx.connection`, or `undefined` when absent.\n * @param onMissing - called once, the first time the service reads absent.\n * @returns the fence every route in this family runs first.\n */\nexport function hostTrustFence(read: () => HostConnectionHandle | undefined, onMissing?: () => void): RouteFence {\n  let missingReported = false\n  return (request) => {\n    const connection = read()\n    if (connection === undefined) {\n      if (!missingReported) {\n        missingReported = true\n        onMissing?.()\n      }\n      return loopbackOnlyFence(request)\n    }\n    try {\n      return connection.requestRejection(request)\n    } catch {\n      // Fail closed: a broken fence must never open file-mutating routes.\n      return 403\n    }\n  }\n}\n\n/**\n * Build every /api/skill-hub route.\n * @param deps - skill registry view + sidecar store + trust fence.\n * @returns the exact-path routes plus the family's 404 catch-all.\n */\nexport function makeRoutes(deps: SkillHubRouteDeps): WebRoute[] {\n  // 各域返回裸 spec，统一在这里包上请求围栏（信任栅栏 → 方法 → 总开关\n  // → JSON 体 → 统一错误映射），新路由不会漏掉围栏。\n  const specs = [\n    ...catalogRoutes(deps),\n    ...configRoutes(deps),\n    ...marketRoutes(deps),\n    ...repoImportRoutes(deps),\n    ...groupRoutes(deps),\n    ...sourceRoutes(deps),\n    ...foreignRoutes(deps),\n    ...zipImportRoutes(deps),\n  ]\n  return [\n    ...specs.map((spec) => createRoute(deps, spec)),\n    // 兜底：本族的未知路径。插件只注册精确路径，未命中的请求会落到宿主的\n    // SPA fallback，那里对 /api/* 统一回 401，排查时极易被误判成鉴权/令牌\n    // 问题，而真实原因是路径写错。这个 prefix 路由把整族纳入命名路由表，\n    // 于是未知路径在宿主侧变成「已命中」→ 由我们回一个写明路径的 404。\n    // 匹配顺序保证安全：宿主先查精确表、再按最长前缀命中，本路由不可能\n    // 抢走任何已注册的精确路由。\n    createRoute(deps, {\n      kind: 'prefix',\n      path: SKILL_HUB_API_ROOT,\n      methods: ['GET', 'POST'],\n      skipGate: true,\n      // 不写盘，且它的价值就是「告诉你路径写错了」：被缺头拦成 403 会把\n      // 拼写问题误导成鉴权问题，正是这条兜底要消除的误判。\n      skipCsrf: true,\n      handler: async ({ res, url }) => {\n        writeError(res, 404, 'unknown skill-hub route: ' + url.pathname + ' (see SKILL_HUB_API in src/protocol/api.ts)')\n      },\n    }),\n  ]\n}\n"
    },
    {
      "path": "src/routes/repo-import.ts",
      "content": "/**\n * 仓库导入域路由：repo 发现 / repoImport 异步导入任务 / progress 轮询 /\n * cancel 取消。从 routes.ts 原样搬出，handler 逻辑不变。\n */\n\nimport { mkdir } from 'node:fs/promises'\nimport { randomUUID } from 'node:crypto'\nimport {\n  SKILL_HUB_API,\n  type RepoDiscoverResponse,\n  type RepoImportCancelResponse,\n  type RepoImportProgressResponse,\n  type RepoImportResponse,\n} from '../protocol.ts'\nimport {\n  cleanupLeftoverImportDirs,\n  collectRepoSkillFiles,\n  discoverRepoEntries,\n  downloadRepoSkill,\n  getLatestCommit,\n  getLatestReleaseTag,\n  isAbortError,\n  listRepoBranches,\n  loadRepoTree,\n  normalizeRepoInput,\n  repoSlug,\n  skillManifest,\n  skillPathIn,\n} from '../repo.ts'\nimport { hashSkillAt, occupancyOf, rootPath } from '../skillfs.ts'\nimport { errorText } from '../error-text.ts'\nimport {\n  homeOf,\n  knownSkillNames,\n  queryParam,\n  readString,\n  readStrings,\n  writeError,\n  writeJson,\n  type RouteSpec,\n  type SkillHubRouteDeps,\n} from './helpers.ts'\nimport { gcImportJobs, importJobs, retireNamePlaceholders, type ImportJob } from './route-state.ts'\n\n/**\n * 导入让位（issue #16）：磁盘上已有同名占位但**没有启用的技能**时，把占位移入\n * 回收站，把名字让给即将导入的真技能。占位有两种 —— 已禁用的发现文件（目录包或\n * 扁平，后者曾长期漏处理：`clearDisabledPlaceholder` 只认 `<name>` 这个目录，\n * 扁平占位占的是 `<name>.md.disabled`，判据为假，分支根本进不去）和没有 `SKILL.md`\n * 的空壳目录。判据统一走 `occupancyOf`，形态判断集中在 `retireNamePlaceholders`。\n *\n * 返回 false = 磁盘上有启用的同名技能（真货），一律不动，交回原本的「跳过」。\n */\nasync function clearDisabledPlaceholder(deps: SkillHubRouteDeps, targetRoot: string, name: string): Promise<boolean> {\n  if ((await occupancyOf(targetRoot, name)).enabled.length > 0) return false\n  return (await retireNamePlaceholders(deps, targetRoot, name)) !== undefined\n}\n\n/** 仓库导入域全部路由 spec（由 routes.ts 经 createRoute 包上统一围栏）。 */\nexport function repoImportRoutes(deps: SkillHubRouteDeps): RouteSpec[] {\n  return [\n    // ---------------------------------------------------------------- repo\n    // Discover importable skills in a public GitHub repo (any top-level root containing SKILL.md).\n    {\n      path: SKILL_HUB_API.repo,\n      methods: ['GET'],\n      handler: async ({ res, url }) => {\n        const input = queryParam(url, 'repo') ?? ''\n        const parsed = normalizeRepoInput(input)\n        if (parsed === null) { writeError(res, 400, 'repo must be owner/repo or a github.com URL'); return }\n        const repo = repoSlug(parsed)\n        // Version resolution: explicit @ref wins; then the market source's\n        // pinned ref (branch picked earlier); then the latest release;\n        // a repo without releases must be pinned to a branch by the user\n        // (branches returned, ref null).\n        let ref = parsed.ref\n        if (ref === undefined || ref === '') {\n          const pinned = await deps.store.getMarketSource(repo)\n          if (pinned?.ref !== undefined && pinned.ref !== '') {\n            ref = pinned.ref\n          }\n        }\n        if (ref === undefined || ref === '') {\n          const releaseTag = await getLatestReleaseTag(repo)\n          if (releaseTag !== undefined) {\n            ref = releaseTag\n            // Auto-pin an existing but unpinned market source to the resolved\n            // release, so the row shows the tracked version from the first scan.\n            const existing = await deps.store.getMarketSource(repo)\n            if (existing !== undefined && (existing.ref === undefined || existing.ref === '')) {\n              await deps.store.setMarketSourceRef(repo, releaseTag)\n            }\n          } else {\n            const branches = await listRepoBranches(repo)\n            if (branches.length === 0) { writeError(res, 404, 'repo has no branches to scan'); return }\n            writeJson(res, 200, { ok: true, repo, ref: null, branches, entries: [] } satisfies RepoDiscoverResponse)\n            return\n          }\n        }\n        const { ref: resolvedRef, tree, truncated } = await loadRepoTree(repo, ref)\n        // 发现态也只看「已启用」：否则已禁用占位会把真技能标成「已存在」并禁掉勾选（issue #16）。\n        const existing = await knownSkillNames(deps, { includeDisabled: false })\n        const entries = discoverRepoEntries(tree, repo, existing)\n        writeJson(res, 200, { ok: true, repo, ref: resolvedRef, entries, ...(truncated ? { truncated: true } : {}) } satisfies RepoDiscoverResponse)\n      },\n    },\n    // ----------------------------------------------------------- repo/import  B方案 Job\n    // Install selected repo skills — now async job (B方案：轮询 + 选项2后台继续)\n    // POST returns jobId instantly (<500ms), GET /progress polls for done.\n    {\n      path: SKILL_HUB_API.repoImport,\n      methods: ['POST'],\n      jsonBody: true,\n      handler: async ({ res, body }) => {\n        const input = readString(body, 'repo').trim()\n        const paths = readStrings(body, 'paths')\n        if (paths.length === 0) { writeError(res, 400, 'paths must be a non-empty array'); return }\n        const parsed = normalizeRepoInput(input)\n        if (parsed === null) { writeError(res, 400, 'repo must be owner/repo or a github.com URL'); return }\n        const repo = repoSlug(parsed)\n        const requestedRef = readString(body, 'ref')\n        const ref = requestedRef !== '' ? requestedRef : parsed.ref\n        const { ref: resolvedRef, tree } = await loadRepoTree(repo, ref)\n        // 导入去重同 discover：已禁用不算「已存在」（issue #16）。\n        const existing = await knownSkillNames(deps, { includeDisabled: false })\n        const entries = discoverRepoEntries(tree, repo, existing)\n        // truncated tree is still usable for the selected paths the user already picked from the prior discover response\n        const byPath = new Map(entries.map((entry) => [entry.path, entry]))\n        const selected = paths.map((path) => byPath.get(path)).filter((entry): entry is NonNullable<typeof entry> => entry !== undefined)\n        if (selected.length === 0) { writeError(res, 400, 'no matching skills for selected paths'); return }\n        if (selected.length > 500) { writeError(res, 400, 'select at most 500 skills per import'); return }\n        const totalBytes = selected.reduce((sum, entry) => sum + entry.totalBytes, 0)\n        if (totalBytes > 200 * 1024 * 1024) { writeError(res, 400, 'selected skills exceed the 200MB import limit'); return }\n\n        let commitSha = ''\n        try {\n          const latest = await getLatestCommit(repo, resolvedRef)\n          commitSha = latest.commitSha\n        } catch {\n          // empty snapshot ok\n        }\n\n        const jobId = 'imp_' + randomUUID().slice(0, 8)\n        const controller = new AbortController()\n        const now = Date.now()\n        const job: ImportJob = {\n          jobId,\n          total: selected.length,\n          done: 0,\n          totalBytes,\n          downloadedBytes: 0,\n          startTime: now,\n          imported: [],\n          skipped: [],\n          failed: [],\n          replaced: [],\n          status: 'running',\n          controller,\n          createdAt: now,\n        }\n        gcImportJobs()\n        importJobs.set(jobId, job)\n\n        // 启动时顺手清理一次残留临时目录（best-effort，不阻塞响应）\n        const targetRootEarly = rootPath('user-dsh', homeOf(deps))\n        void cleanupLeftoverImportDirs(targetRootEarly).catch(() => {})\n\n        // 后台执行，不阻塞响应（选项2：关面板也继续跑，唯有 /cancel 才 abort）\n        void (async () => {\n          const targetRoot = rootPath('user-dsh', homeOf(deps))\n          await mkdir(targetRoot, { recursive: true })\n          const defaultTag = await deps.store.getDefaultTag()\n          let needInvalidate = false\n          for (const entry of selected) {\n            if (controller.signal.aborted) break\n            job.current = entry.name\n            job.currentFile = entry.path\n            if (entry.existing) {\n              job.skipped.push({ name: entry.name, reason: 'exists' })\n              job.downloadedBytes += entry.totalBytes\n              job.done += 1\n              continue\n            }\n            // 磁盘上有同名占位。若它只是一个已禁用的占位（目录包或扁平）或一个空壳\n            // 目录，先把旧东西移入回收站再继续导入；有启用的同名技能时退回「跳过」\n            // （issue #16）。\n            const occupancy = await occupancyOf(targetRoot, entry.name)\n            if (occupancy.enabled.length > 0 || occupancy.disabled.length > 0 || occupancy.bareDir !== undefined) {\n              let cleared = false\n              try {\n                cleared = await clearDisabledPlaceholder(deps, targetRoot, entry.name)\n              } catch {\n                cleared = false\n              }\n              if (!cleared) {\n                job.skipped.push({ name: entry.name, reason: 'exists' })\n                job.downloadedBytes += entry.totalBytes\n                job.done += 1\n                continue\n              }\n              // 占位已经进了回收站（可恢复）。即使随后的下载失败也必须如实\n              // 上报，否则用户不知道自己的占位被挪走了。\n              job.replaced.push(entry.name)\n            }\n            if (controller.signal.aborted) break\n            const files = collectRepoSkillFiles(tree, entry.dir)\n            try {\n              const result = await downloadRepoSkill(repo, resolvedRef, entry, files, targetRoot, fetch, controller.signal, (bytes, file) => {\n                job.downloadedBytes += bytes\n                job.currentFile = skillPathIn(entry.dir, file)\n              })\n              await deps.store.addSourceSkill(repo, entry.root, commitSha, resolvedRef, entry.name)\n              await deps.store.mergeSourceManifest(repo, skillManifest(tree, entry.dir), entry.dir)\n              // 采集刚落盘内容的哈希：这是之后区分「上游变了」与「本地改过」的唯一依据。\n              const hash = await hashSkillAt(result.skillPath)\n              if (hash !== undefined) await deps.store.setSourceSkillHash(repo, entry.name, hash)\n              if (defaultTag !== undefined) await deps.store.addSkillToTag(defaultTag.id, entry.name)\n              job.imported.push({ name: entry.name, origin: entry.origin, path: result.skillPath })\n              needInvalidate = true\n            } catch (error) {\n              if (isAbortError(error) || controller.signal.aborted) {\n                // 取消时不记为 failed，保留已完成的 imported/skipped，直接跳出\n                break\n              }\n              job.failed.push({ name: entry.name, error: errorText(error) })\n            } finally {\n              job.done += 1\n            }\n          }\n          if (controller.signal.aborted) {\n            job.status = 'cancelled'\n            job.current = undefined\n            job.currentFile = undefined\n          } else {\n            job.status = 'done'\n            job.current = undefined\n            job.currentFile = undefined\n            // 确保字节进度最终对齐（避免浮点/并发尾差）\n            job.downloadedBytes = job.totalBytes\n          }\n          if (needInvalidate) deps.invalidate?.()\n        })().catch((error) => {\n          job.status = 'error'\n          job.error = errorText(error)\n          job.current = undefined\n          job.currentFile = undefined\n        })\n\n        writeJson(res, 200, { ok: true, jobId, total: selected.length, totalBytes } satisfies RepoImportResponse)\n      },\n    },\n    // 进度轮询（含字节级进度和速度）\n    {\n      path: SKILL_HUB_API.repoImportProgress,\n      methods: ['GET'],\n      handler: async ({ res, url }) => {\n        const jobId = queryParam(url, 'jobId') ?? ''\n        if (jobId === '') { writeError(res, 400, 'jobId is required'); return }\n        const job = importJobs.get(jobId)\n        if (job === undefined) { writeError(res, 404, 'import job not found: ' + jobId); return }\n        const elapsedSec = Math.max(0.5, (Date.now() - job.startTime) / 1000)\n        const bytesPerSecond = job.status === 'running' ? Math.round(job.downloadedBytes / elapsedSec) : undefined\n        writeJson(res, 200, {\n          ok: true,\n          jobId: job.jobId,\n          status: job.status,\n          total: job.total,\n          done: job.done,\n          ...(job.current !== undefined ? { current: job.current } : {}),\n          ...(job.currentFile !== undefined ? { currentFile: job.currentFile } : {}),\n          totalBytes: job.totalBytes,\n          downloadedBytes: job.downloadedBytes,\n          ...(bytesPerSecond !== undefined ? { bytesPerSecond } : {}),\n          imported: [...job.imported],\n          skipped: [...job.skipped],\n          failed: [...job.failed],\n          ...(job.replaced.length > 0 ? { replaced: [...job.replaced] } : {}),\n          ...(job.error !== undefined ? { error: job.error } : {}),\n        } satisfies RepoImportProgressResponse)\n      },\n    },\n    // 取消任务（选项2：唯有点取消才停）\n    {\n      path: SKILL_HUB_API.repoImportCancel,\n      methods: ['POST'],\n      jsonBody: true,\n      handler: async ({ res, body }) => {\n        const jobId = readString(body, 'jobId')\n        if (jobId === '') { writeError(res, 400, 'jobId is required'); return }\n        const job = importJobs.get(jobId)\n        if (job === undefined) { writeError(res, 404, 'import job not found: ' + jobId); return }\n        if (job.status === 'running') {\n          job.controller.abort()\n          job.status = 'cancelled'\n        }\n        writeJson(res, 200, { ok: true, jobId: job.jobId, status: job.status as 'cancelled' | 'done' } satisfies RepoImportCancelResponse)\n      },\n    },\n  ]\n}\n"
    },
    {
      "path": "src/routes/sources.ts",
      "content": "/**\n * 来源跟踪域路由：sources 列表 / check 上游更新 / sync 同步 / delete 跟进\n * 删除 / restore 恢复 / trash/clear 清空回收站。从 routes.ts 原样搬出，\n * handler 逻辑不变。\n */\n\nimport { mkdir, readdir, rm } from 'node:fs/promises'\nimport { join } from 'node:path'\nimport { isSkillName } from '@deepseek-ai/dsh-skill'\nimport {\n  SKILL_HUB_API,\n  type SourceCheckResponse,\n  type SourceCheckResult,\n  type SourceDeleteResponse,\n  type SourceRestoreResponse,\n  type SourceSyncResponse,\n  type SourcesResponse,\n  type SourceTrashClearResponse,\n} from '../protocol.ts'\nimport {\n  collectRepoSkillFiles,\n  diffRemoteSkills,\n  downloadRepoSkill,\n  getLatestCommit,\n  loadRepoTreeAt,\n  normalizeRepoInput,\n  repoSkillEntry,\n  repoSlug,\n  skillDirOf,\n  skillFileAt,\n  skillManifest,\n} from '../repo.ts'\nimport { clearTrash, hashSkillAt, occupancyOf, restoreSkill, rootOfPath, rootPath, trashSkill, trashSourceOf, WRITABLE_ROOTS } from '../skillfs.ts'\nimport { errorText } from '../error-text.ts'\nimport { mapConcurrent } from '../concurrency.ts'\nimport {\n  buildCollections,\n  homeOf,\n  pathExists,\n  readString,\n  readStrings,\n  writeError,\n  writeJson,\n  type RouteSpec,\n  type SkillHubRouteDeps,\n} from './helpers.ts'\nimport { MIN_CHECK_INTERVAL_MS, lastSourceCheck, replaceInPlace, retireNamePlaceholders } from './route-state.ts'\n\n/**\n * 本地被改过的技能：磁盘内容哈希 ≠ 导入/同步时记录的哈希。\n *\n * 只对「记录里已有哈希」的技能判定 —— 旧记录没采集过哈希，硬比会得到\n * 「全部已改」的假警报。技能目录读不到（被删/被移走）同样不算改过：\n * 那是另一种状态，由发现诊断去报。\n */\nasync function localModifiedSkills(source: { skills: readonly string[]; localHashes?: Record<string, string> }, home: string): Promise<string[]> {\n  const hashes = source.localHashes\n  if (hashes === undefined || Object.keys(hashes).length === 0) return []\n  const base = rootPath('user-dsh', home)\n  const modified: string[] = []\n  // 有界并发，与 scanDiagnostics 同一理由：一个来源可能跟踪几十个技能，\n  // 裸 Promise.all 会同时打开上百个文件句柄。\n  await mapConcurrent(source.skills, 8, async (name) => {\n    const expected = hashes[name]\n    if (expected === undefined) return\n    const occupancy = await occupancyOf(base, name)\n    const path = occupancy.enabled[0]\n    if (path === undefined) return\n    const actual = await hashSkillAt(path)\n    if (actual !== undefined && actual !== expected) modified.push(name)\n  })\n  return modified.sort((a, b) => a.localeCompare(b))\n}\n\n/** 来源跟踪域全部路由 spec（由 routes.ts 经 createRoute 包上统一围栏）。 */\nexport function sourceRoutes(deps: SkillHubRouteDeps): RouteSpec[] {\n  return [\n    // ------------------------------------------------------------- sources\n    // 来源列表 + 派生 origin 映射 + 集合组 + 回收站。\n    {\n      path: SKILL_HUB_API.sources,\n      methods: ['GET'],\n      handler: async ({ res }) => {\n        const [sources, origins, trash, collectionOrder] = await Promise.all([deps.store.listSources(), deps.store.listOrigins(), deps.store.listTrash(), deps.store.getCollectionOrder()])\n        writeJson(res, 200, { ok: true, sources, origins, collections: buildCollections(origins, collectionOrder), trash } satisfies SourcesResponse)\n      },\n    },\n    // -------------------------------------------------------- sources/check\n    // 检查指定（或全部）来源的上游更新。每个来源最多 1 次 commit 请求；\n    // 仅当 commit 变化时再拉一次 tree 做逐技能差异。5 分钟节流。\n    {\n      path: SKILL_HUB_API.sourceCheck,\n      methods: ['POST'],\n      jsonBody: true,\n      handler: async ({ res, body }) => {\n        const rawRepo = readString(body, 'repo')\n        let only: string | undefined\n        if (rawRepo !== '') {\n          // Normalize URLs/slugs the same way every other route does, so a\n          // check for \"https://github.com/a/b\" finds the \"a/b\" record.\n          const parsedOnly = normalizeRepoInput(rawRepo)\n          if (parsedOnly === null) { writeError(res, 400, 'repo must be owner/repo or a github.com URL'); return }\n          only = repoSlug(parsedOnly)\n        }\n        const source = only !== undefined ? await deps.store.getSource(only) : undefined\n        if (only !== undefined && source === undefined) { writeError(res, 404, 'source not found: ' + only); return }\n        const sources = source !== undefined ? [source] : await deps.store.listSources()\n        if (lastSourceCheck.size > 500) lastSourceCheck.clear()\n        const home = homeOf(deps)\n        const results: SourceCheckResult[] = []\n        for (const item of sources) {\n          // 本地改动是磁盘事实，与网络检查成败无关，所以放在节流判断之前。\n          const modified = await localModifiedSkills(item, home)\n          const base = {\n            repo: item.repo,\n            ...(item.ref !== undefined ? { ref: item.ref } : {}),\n            ...(modified.length > 0 ? { localModified: modified } : {}),\n          }\n          const now = Date.now()\n          const last = lastSourceCheck.get(item.repo) ?? 0\n          if (now - last < MIN_CHECK_INTERVAL_MS) {\n            results.push({ ...base, changed: false, updated: [], deleted: [], throttled: true })\n            continue\n          }\n          try {\n            const latest = await getLatestCommit(item.repo, item.ref)\n            if (item.commitSha === '') {\n              // Migrated/legacy record without a snapshot: backfill the\n              // commit now and report \"unverified\" instead of claiming every\n              // skill is updated (there is no baseline to diff against yet).\n              await deps.store.setSourceCommit(item.repo, latest.commitSha)\n              lastSourceCheck.set(item.repo, now)\n              results.push({ ...base, changed: false, updated: [], deleted: [], unverified: true, commitSha: latest.commitSha })\n              continue\n            }\n            if (latest.commitSha === item.commitSha) {\n              lastSourceCheck.set(item.repo, now)\n              results.push({ ...base, changed: false, updated: [], deleted: [] })\n              continue\n            }\n            const tree = await loadRepoTreeAt(item.repo, latest.treeSha)\n            const diff = diffRemoteSkills(tree, item)\n            // Only a fully successful check starts the throttle window: a\n            // failed tree/download must be retryable immediately.\n            lastSourceCheck.set(item.repo, now)\n            results.push({ ...base, changed: true, commitSha: latest.commitSha, updated: diff.updated, deleted: diff.deleted })\n          } catch (error) {\n            results.push({ ...base, changed: false, updated: [], deleted: [], error: errorText(error) })\n          }\n        }\n        writeJson(res, 200, { ok: true, results } satisfies SourceCheckResponse)\n      },\n    },\n    // --------------------------------------------------------- sources/sync\n    // 按上游重新下载所选（或全部）技能并更新 commit 快照与 manifest。\n    {\n      path: SKILL_HUB_API.sourceSync,\n      methods: ['POST'],\n      jsonBody: true,\n      handler: async ({ res, body }) => {\n        const repo = readString(body, 'repo').trim()\n        if (repo === '') { writeError(res, 400, 'repo is required'); return }\n        // 未传 skills（不是数组）表示\"全部\"，空数组表示\"一个都不选\"。\n        const selected = Array.isArray(body.skills) ? readStrings(body, 'skills') : undefined\n        const source = await deps.store.getSource(repo)\n        if (source === undefined) { writeError(res, 404, 'source not found: ' + repo); return }\n        const targets = selected !== undefined ? selected : source.skills\n        const latest = await getLatestCommit(repo, source.ref)\n        const tree = await loadRepoTreeAt(repo, latest.treeSha)\n        const targetRoot = rootPath('user-dsh', homeOf(deps))\n        await mkdir(targetRoot, { recursive: true })\n        const synced: string[] = []\n        const overwritten: string[] = []\n        const failed: Array<{ name: string; error: string }> = []\n        for (const name of targets) {\n          // Sync writes under the user root: only accept real skill names\n          // this source actually tracks (a bare join would otherwise fold\n          // `..` segments out of the writable root).\n          if (!isSkillName(name) || !source.skills.includes(name)) {\n            failed.push({ name, error: 'skill is not tracked by this source' })\n            continue\n          }\n          try {\n            const entry = repoSkillEntry(name, source.root, repo)\n            // 上游可能用分类子目录（skills/engineering/<name>/）且目录会移动：\n            // 先在上游 tree 里搜真实位置，manifest 兜底，否则嵌套技能会 404。\n            entry.dir = skillDirOf(source, name, tree.map((item) => item.path))\n            entry.path = skillFileAt(entry.dir)\n            const files = collectRepoSkillFiles(tree, entry.dir)\n            if (files.length === 0) { failed.push({ name, error: 'skill missing upstream' }); continue }\n            const targetDir = join(targetRoot, name)\n            const record = await deps.store.getDisabled(name)\n            const occupancy = await occupancyOf(targetRoot, name)\n            // 落盘位置永远是目录包，所以本地无论是目录包还是扁平文件（启用或禁用）\n            // 都得先让开，否则同名两形态会并存（issue #16 类）。\n            const download = () => downloadRepoSkill(repo, latest.commitSha, entry, files, targetRoot)\n            // 覆盖前的如实上报：本地内容与记录不符时，这次同步会丢掉用户的改动。\n            // 是否继续由调用方（GUI 确认弹窗）决定，这里只负责不隐瞒。\n            const expectedHash = source.localHashes?.[name]\n            const localPath = occupancy.enabled[0]\n            if (expectedHash !== undefined && localPath !== undefined) {\n              const actualHash = await hashSkillAt(localPath)\n              if (actualHash !== undefined && actualHash !== expectedHash) overwritten.push(name)\n            }\n            // 1) 禁用件与空壳让位（顺带清掉 sidecar 禁用记录）。\n            await retireNamePlaceholders(deps, targetRoot, name)\n            // 2) 启用件按「替换」语义处理：先挪到点前缀备份，下载失败则原样恢复。\n            const enabled = occupancy.enabled[0]\n            if (enabled !== undefined) {\n              await replaceInPlace(trashSourceOf(enabled), download)\n            } else {\n              await download()\n            }\n            // 同步后保持停用状态：只重写策略，不再把新的 SKILL.md 改名成\n            // SKILL.md.disabled（第一轮重构后停用不碰磁盘文件）。\n            // 记录必须**无条件写回** —— 上面的 retireNamePlaceholders 可能已经\n            // 删过一遍，漏写会让「同步一个已停用的技能」悄悄复活。\n            const policyPath = join(targetDir, 'SKILL.md')\n            if (record !== undefined) {\n              await deps.store.addInvocationOverride(policyPath)\n              await deps.store.addDisabled({ ...record, path: policyPath })\n            } else {\n              await deps.store.removeInvocationOverride(policyPath)\n              await deps.store.removeDisabled(name)\n            }\n            await deps.store.mergeSourceManifest(repo, skillManifest(tree, entry.dir), entry.dir)\n            // 落盘后的实际内容才是新基线；停用已不再改文件名，只认启用态发现文件。\n            const settled = await occupancyOf(targetRoot, name)\n            const settledPath = settled.enabled[0]\n            if (settledPath !== undefined) {\n              const hash = await hashSkillAt(settledPath)\n              if (hash !== undefined) await deps.store.setSourceSkillHash(repo, name, hash)\n            }\n            synced.push(name)\n          } catch (error) {\n            failed.push({ name, error: errorText(error) })\n          }\n        }\n        // Only advance the commit snapshot when the full tracked set is clean\n        // against the target tree. A partial selection (or an empty one) must\n        // leave the old baseline so the next check still reports the skills\n        // that were not synced. The response reports the committed value\n        // actually in the store, not the upstream latest.\n        if (failed.length === 0 && targets.length > 0) {\n          const current = await deps.store.getSource(repo)\n          const remaining = current !== undefined ? diffRemoteSkills(tree, current) : { updated: [], deleted: [] }\n          if (remaining.updated.length === 0 && remaining.deleted.length === 0) {\n            await deps.store.setSourceCommit(repo, latest.commitSha)\n          }\n        }\n        // The disk changed during this request; the old 5-minute throttle\n        // would otherwise hide the next check behind stale state.\n        lastSourceCheck.delete(repo)\n        deps.invalidate?.()\n        const settled = await deps.store.getSource(repo)\n        writeJson(res, 200, { ok: true, repo, commitSha: settled?.commitSha ?? source.commitSha, synced, ...(overwritten.length > 0 ? { overwritten } : {}), failed } satisfies SourceSyncResponse)\n      },\n    },\n    // ------------------------------------------------------- sources/delete\n    // 跟进上游删除：把所选技能的本地目录移入回收站（可恢复）。\n    {\n      path: SKILL_HUB_API.sourceDelete,\n      methods: ['POST'],\n      jsonBody: true,\n      handler: async ({ res, body }) => {\n        const repo = readString(body, 'repo').trim()\n        const skills = readStrings(body, 'skills')\n        if (repo === '') { writeError(res, 400, 'repo is required'); return }\n        if (skills.length === 0) { writeError(res, 400, 'skills must be a non-empty array'); return }\n        const source = await deps.store.getSource(repo)\n        if (source === undefined) { writeError(res, 404, 'source not found: ' + repo); return }\n        const home = homeOf(deps)\n        const trashed: string[] = []\n        const failed: Array<{ name: string; error: string }> = []\n        const sourceNames = new Set(source.skills)\n        for (const name of skills) {\n          // Every name must be a real kebab-case skill that this source\n          // actually tracks; anything else must never touch the filesystem\n          // (a bare `join` would otherwise fold `..` segments out of the\n          // writable root — see the path-containment assert below).\n          if (!isSkillName(name) || !sourceNames.has(name)) {\n            failed.push({ name, error: 'skill is not tracked by this source' })\n            continue\n          }\n          // Resolve the on-disk occupation instead of assuming a `<root>/<name>`\n          // directory: the tracked skill can equally be a flat `<name>.md` file.\n          // A paused skill keeps its discovery file, so `enabled[0]` covers it too.\n          const base = rootPath('user-dsh', home)\n          const occupancy = await occupancyOf(base, name)\n          const existing = occupancy.enabled[0] ?? occupancy.bareDir\n          if (existing === undefined) {\n            failed.push({ name, error: 'skill not found on disk' })\n            continue\n          }\n          if (rootOfPath(existing, home) === undefined) {\n            failed.push({ name, error: 'skill path is outside the hub writable roots' })\n            continue\n          }\n          try {\n            // 入回收站前快照来源与角色归属，恢复时挂回（见 sourceRestore）。\n            const tagIds = (await deps.store.listTags()).filter((tag) => tag.skillNames.includes(name)).map((tag) => tag.id)\n            const { path, source: trashSource } = await trashSkill(existing)\n            await deps.store.addTrash({\n              name,\n              path,\n              movedAt: Date.now(),\n              sourcePath: trashSource,\n              origin: { repo: source.repo, root: source.root, ...(source.ref !== undefined && source.ref !== '' ? { ref: source.ref } : {}), commitSha: source.commitSha },\n              ...(tagIds.length > 0 ? { tagIds } : {}),\n            })\n            await deps.store.removeDisabled(name)\n            await deps.store.removeSkillFromTags(name)\n            trashed.push(name)\n          } catch (error) {\n            failed.push({ name, error: errorText(error) })\n          }\n        }\n        if (trashed.length > 0) {\n          await deps.store.setSourceSkills(repo, source.skills.filter((n) => !trashed.includes(n)))\n          // 跟进删除后，被删技能已从 source.skills 移除；如果其余技能都已\n          // 对齐目标 tree，就把 commit 基线推进到最新。否则下一次检查会因\n          // commit 不同却既无 updated 也无 deleted，永久显示「有更新」空徽章。\n          try {\n            const latest = await getLatestCommit(repo, source.ref)\n            const tree = await loadRepoTreeAt(repo, latest.treeSha)\n            const current = await deps.store.getSource(repo)\n            if (current !== undefined) {\n              const remaining = diffRemoteSkills(tree, current)\n              if (remaining.updated.length === 0 && remaining.deleted.length === 0) {\n                await deps.store.setSourceCommit(repo, latest.commitSha)\n              }\n            }\n          } catch {\n            // 删除本身已成功；基线推进失败时下次检查会重新尝试。\n          }\n          lastSourceCheck.delete(repo)\n          deps.invalidate?.()\n        }\n        writeJson(res, 200, { ok: true, trashed, failed } satisfies SourceDeleteResponse)\n      },\n    },\n    // ------------------------------------------------------ sources/restore\n    // 从回收站恢复一个技能目录。\n    {\n      path: SKILL_HUB_API.sourceRestore,\n      methods: ['POST'],\n      jsonBody: true,\n      handler: async ({ res, body }) => {\n        const name = readString(body, 'name')\n        if (name === '') { writeError(res, 400, 'name is required'); return }\n        const entry = await deps.store.getTrash(name)\n        if (entry === undefined) { writeError(res, 404, 'trash entry not found: ' + name); return }\n        const home = homeOf(deps)\n        const target = entry.sourcePath ?? join(rootPath('user-dsh', home), name)\n        if (await pathExists(target)) {\n          writeError(res, 409, 'skill already exists: ' + name)\n          return\n        }\n        const path = await restoreSkill(entry, home)\n        // 恢复来源归属（入回收站前快照的来源记录）与角色成员，否则恢复后\n        // 的技能会变成「个人技能」并脱离原角色。\n        if (entry.origin !== undefined) {\n          await deps.store.addSourceSkill(entry.origin.repo, entry.origin.root, entry.origin.commitSha, entry.origin.ref, name)\n        }\n        for (const tagId of entry.tagIds ?? []) {\n          await deps.store.addSkillToTag(tagId, name)\n        }\n        await deps.store.removeTrash(entry.path)\n        deps.invalidate?.()\n        writeJson(res, 200, { ok: true, name, path } satisfies SourceRestoreResponse)\n      },\n    },\n    // ------------------------------------------------- sources/trash/clear\n    // 清空回收站：永久删除 .trash 里的技能，失败项保留可重试。\n    {\n      path: SKILL_HUB_API.sourceTrashClear,\n      methods: ['POST'],\n      handler: async ({ res }) => {\n        const home = homeOf(deps)\n        const entries = await deps.store.listTrash()\n        const deleted: string[] = []\n        const removedPaths: string[] = []\n        const failed: Array<{ name: string; error: string }> = []\n        for (const entry of entries) {\n          try {\n            await clearTrash(entry, home)\n            // A permanently deleted skill must not linger in user groups.\n            await deps.store.removeSkillFromTags(entry.name)\n            deleted.push(entry.name)\n            removedPaths.push(entry.path)\n          } catch (error) {\n            failed.push({ name: entry.name, error: errorText(error) })\n          }\n        }\n        for (const path of removedPaths) await deps.store.removeTrash(path)\n        // 回收站记录按名字索引：同名技能先后两次入站时旧记录被覆盖，但它的\n        // `<name>-<时间戳>` 目录还留在盘上，任何记录都指不到它 → 永久孤儿。\n        // 「清空回收站」正是它的回收时机，顺手扫掉并如实上报。\n        const orphans = await sweepOrphanTrash(deps, home, failed)\n        if (deleted.length > 0 || orphans.length > 0) deps.invalidate?.()\n        writeJson(res, 200, {\n          ok: true,\n          deleted,\n          failed,\n          ...(orphans.length > 0 ? { orphans } : {}),\n        } satisfies SourceTrashClearResponse)\n      },\n    },\n  ]\n}\n\n/**\n * 删除两个可写根 `.trash` 下不被任何回收站记录引用的残留目录。\n * 只扫 `.trash` 的直接子项、跳过点开头项，失败项并入 `failed`（保留可重试）。\n */\nasync function sweepOrphanTrash(deps: SkillHubRouteDeps, home: string, failed: Array<{ name: string; error: string }>): Promise<string[]> {\n  const referenced = new Set((await deps.store.listTrash()).map((entry) => entry.path))\n  const orphans: string[] = []\n  for (const root of WRITABLE_ROOTS) {\n    const trashDir = join(rootPath(root, home), '.trash')\n    let names: string[]\n    try {\n      names = await readdir(trashDir)\n    } catch {\n      continue // 该根没有回收站目录\n    }\n    for (const name of names) {\n      if (name.startsWith('.')) continue\n      const full = join(trashDir, name)\n      if (referenced.has(full)) continue\n      try {\n        await rm(full, { recursive: true, force: true })\n        orphans.push(full)\n      } catch (error) {\n        failed.push({ name, error: errorText(error) })\n      }\n    }\n  }\n  return orphans\n}\n"
